<?php /** @var string $entity */ /** @var array<string,mixed> $d */ /** @var ?array<string,mixed> $row */ /** @var array<string,mixed> $values */ /** @var list<array<string,mixed>> $media */ /** @var list<array<string,mixed>> $services */ /** @var bool $canEdit */ /** @var bool $canPublish */
use Vertex\Core\Session;
$old = Session::get('_old', []); $old = is_array($old) ? $old : [];
$val = static function (string $name, mixed $default = '') use ($old, $values): mixed { return array_key_exists($name, $old) ? $old[$name] : ($values[$name] ?? $default); };
$action = '/admin/site/' . $entity . ($row === null ? '' : '/' . $row['public_id']);
$status = (string) ($row['status'] ?? 'draft'); ?>
<div class="page-head"><div><p class="eyebrow">Website · <?= e($d['label']) ?></p><h1><?= $row === null ? 'New ' . e($d['singular']) : e((string) $row[$d['title']]) ?><?php if ($row !== null) : ?> <span class="badge badge-sys-<?= $status === 'published' ? 'ok' : 'warn' ?>"><?= e($status) ?></span><?php endif; ?></h1></div>
    <div><?php if ($row !== null && $entity === 'policies') : ?><a class="btn btn-ghost" href="/admin/site/policies/<?= e($row['public_id']) ?>/versions">History (v<?= (int) $row['version_no'] ?>)</a> <?php endif; ?>
        <?php if ($row !== null && $status === 'published') : $url = $entity === 'policies' ? '/' . $row['slug'] : ($d['slug'] ?? false ? $d['public'] . $row['slug'] : $d['public']); ?><a class="btn btn-ghost" href="<?= e($url) ?>" target="_blank" rel="noopener">View on website</a> <?php endif; ?>
        <a class="btn btn-ghost" href="/admin/site/<?= e($entity) ?>">All <?= e(strtolower($d['label'])) ?></a></div></div>
<?= \Vertex\Core\View::partial('cms-nav') ?>
<?php if ($entity === 'policies' && $row !== null && preg_match('/\[ADMIN TO COMPLETE/i', (string) $row['body'])) : ?><div class="alert alert-error" role="status"><p>This draft still contains an <strong>[ADMIN TO COMPLETE]</strong> note. Replace it with the real details and delete the line: the policy cannot be published until then. Have it reviewed by someone qualified.</p></div><?php endif; ?>
<?php if ($row !== null && $status === 'published' && !$canPublish) : ?><div class="alert alert-error" role="status"><p>This is live. Changing it needs publish rights.</p></div><?php endif; ?>
<div class="panel"><form method="post" action="<?= e($action) ?>" class="form-grid"><?= csrf_field() ?>
    <?php if ($d['slug'] ?? false) : ?><div class="field"><label for="f-slug">Web address</label><input id="f-slug" name="slug" maxlength="80" value="<?= e((string) $val('slug')) ?>" placeholder="leave empty to make it from the title"><p class="hint">Shown as <?= e($d['public']) ?>…</p></div><?php endif; ?>
    <?php foreach ($d['fields'] as $name => $f) : $id = 'f-' . $name; $v = $val($name, $f['kind'] === 'gallery' || $f['kind'] === 'multi' ? [] : ($f['kind'] === 'bool' ? false : '')); ?>
        <?php if ($f['kind'] === 'bool') : ?><div class="field"><label class="check"><input type="checkbox" name="<?= e($name) ?>" value="1"<?= $v && $v !== '0' ? ' checked' : '' ?><?= $canEdit ? '' : ' disabled' ?>> <?= e($f['label']) ?></label></div>
        <?php elseif ($f['kind'] === 'gallery') : $v = (array) $v; ?><fieldset class="field"><legend><?= e($f['label']) ?></legend><div class="check-grid"><?php foreach ($media as $m) : ?><label class="check"><input type="checkbox" name="<?= e($name) ?>[]" value="<?= e($m['public_id']) ?>"<?= in_array($m['public_id'], $v, true) ? ' checked' : '' ?>> <span><?= e($m['original_name']) ?></span></label><?php endforeach; ?><?php if ($media === []) : ?><span class="muted">No pictures yet. <a href="/admin/cms/media">Upload some</a>.</span><?php endif; ?></div></fieldset>
        <?php elseif ($f['kind'] === 'multi') : $v = (array) $v; ?><fieldset class="field"><legend><?= e($f['label']) ?></legend><div class="check-grid"><?php foreach ($services as $s) : if ($row !== null && $s['id'] === $row['id']) { continue; } ?><label class="check"><input type="checkbox" name="<?= e($name) ?>[]" value="<?= e($s['slug']) ?>"<?= in_array($s['slug'], $v, true) ? ' checked' : '' ?>> <span><?= e($s['name']) ?></span></label><?php endforeach; ?></div></fieldset>
        <?php else : ?><div class="field"><label for="<?= e($id) ?>"><?= e($f['label']) ?><?= !empty($f['required']) ? ' *' : '' ?></label>
            <?php if ($f['kind'] === 'textarea' || $f['kind'] === 'lines') : ?><textarea id="<?= e($id) ?>" name="<?= e($name) ?>" rows="<?= $f['kind'] === 'lines' ? 6 : ((int) ($f['max'] ?? 0) > 5000 ? 18 : 5) ?>" maxlength="<?= (int) $f['max'] ?>"<?= !empty($f['required']) ? ' required' : '' ?><?= $canEdit ? '' : ' disabled' ?>><?= e((string) $v) ?></textarea>
            <?php elseif ($f['kind'] === 'select') : ?><select id="<?= e($id) ?>" name="<?= e($name) ?>"<?= !empty($f['required']) ? ' required' : '' ?><?= $canEdit ? '' : ' disabled' ?>><option value="">Choose…</option><?php foreach ($f['options'] as $ov => $ol) : ?><option value="<?= e((string) $ov) ?>"<?= (string) $v === (string) $ov ? ' selected' : '' ?>><?= e($ol) ?></option><?php endforeach; ?></select>
            <?php elseif ($f['kind'] === 'media') : ?><select id="<?= e($id) ?>" name="<?= e($name) ?>"<?= $canEdit ? '' : ' disabled' ?>><option value="">— none —</option><?php foreach ($media as $m) : ?><option value="<?= e($m['public_id']) ?>"<?= (string) $v === $m['public_id'] ? ' selected' : '' ?>><?= e($m['original_name']) ?></option><?php endforeach; ?></select><?php if ($media === []) : ?><p class="hint">No pictures yet. <a href="/admin/cms/media">Upload one first</a>.</p><?php endif; ?>
            <?php else : ?><input id="<?= e($id) ?>" name="<?= e($name) ?>" type="<?= $f['kind'] === 'date' ? 'date' : 'text' ?>" maxlength="<?= (int) ($f['max'] ?? 300) ?>" value="<?= e((string) $v) ?>"<?= !empty($f['required']) ? ' required' : '' ?><?= $canEdit ? '' : ' disabled' ?>><?php endif; ?>
            <?php if (!empty($f['help'])) : ?><p class="hint"><?= e($f['help']) ?></p><?php endif; ?></div>
        <?php endif; ?>
    <?php endforeach; ?>
    <?php if ($canEdit) : ?><div class="form-actions"><button class="btn btn-primary" type="submit">Save<?= $row === null ? ' as draft' : '' ?></button></div><?php endif; ?></form></div>
<?php if ($row !== null && ($canPublish || !empty($canEdit))) : ?>
<div class="panel"><h2>Visibility</h2><p class="muted"><?= $status === 'published' ? 'Visitors can see this now.' : 'Visitors cannot see this yet.' ?></p>
    <?php if ($canPublish) : ?>
        <?php if ($status !== 'published') : ?><form method="post" action="<?= e($action) ?>/status" class="inline-form"><?= csrf_field() ?><button class="btn btn-primary" name="action" value="publish" type="submit">Publish</button></form><?php endif; ?>
        <?php if ($status === 'published') : ?><form method="post" action="<?= e($action) ?>/status" class="inline-form"><?= csrf_field() ?><input name="confirm_password" type="password" required placeholder="Your password" aria-label="Your password" autocomplete="current-password"><button class="btn btn-ghost" name="action" value="unpublish" type="submit">Unpublish (back to draft)</button></form><?php endif; ?>
        <?php if ($entity === 'jobs' && $status === 'published') : ?><form method="post" action="<?= e($action) ?>/status" class="inline-form"><?= csrf_field() ?><input name="confirm_password" type="password" required placeholder="Your password" aria-label="Your password" autocomplete="current-password"><button class="btn btn-ghost" name="action" value="close" type="submit">Close this opening</button></form><?php endif; ?>
        <?php if ($status !== 'archived') : ?><form method="post" action="<?= e($action) ?>/status" class="inline-form"><?= csrf_field() ?><input name="confirm_password" type="password" required placeholder="Your password" aria-label="Your password" autocomplete="current-password"><button class="btn btn-ghost" name="action" value="archive" type="submit">Archive</button></form><?php endif; ?>
        <?php if (empty($d['noDelete'])) : ?><form method="post" action="<?= e($action) ?>/status" class="inline-form" data-confirm="Delete this permanently?"><?= csrf_field() ?><input name="confirm_password" type="password" required placeholder="Your password" aria-label="Your password" autocomplete="current-password"><button class="btn btn-danger" name="action" value="delete" type="submit">Delete</button></form><?php endif; ?>
    <?php endif; ?></div><?php endif; ?>
